(688553, 72140, 10170, '<td valign="top">Nicely done and meets the challenge well.</td>', 'Nicely done and meets the challenge well.', '2004-04-28 04:11:35.000000', NULL, 1),
(688555, 72565, 10170, '<td valign="top">Nicely done, especially the way you have posed the plastic doll in the background (kidding, she is a far better shape than Barbie!).  Fits the chellenge perfectly, and would have also worked well for silhouettes.</td>', 'Nicely done, especially the way you have posed the plastic doll in the background (kidding, she is a far better shape than Barbie!).  Fits the chellenge perfectly, and would have also worked well for silhouettes.', '2004-04-28 04:12:54.000000', NULL, 1),
