(688705, 71479, 9295, '<td valign="top">I think in this particular case, cropping to center the focal point would have been more effective.  Nice interpretation of the challenge.</td>', 'I think in this particular case, cropping to center the focal point would have been more effective.  Nice interpretation of the challenge.', '2004-04-28 09:07:19.000000', NULL, 1),
(688707, 72402, 9295, '<td valign="top">I like this photo a lot but I don''t see where it fits the challenge. Nothing about it really defines proportion for me. However, the lighting makes this an interesting capture.</td>', 'I like this photo a lot but I don''t see where it fits the challenge. Nothing about it really defines proportion for me. However, the lighting makes this an interesting capture.', '2004-04-28 09:10:34.000000', NULL, 1),
