(689789, 71912, 2535, '<td valign="top">neat idea</td>', 'neat idea', '2004-04-28 20:53:52.000000', NULL, 1),
(689790, 72539, 7322, '<td valign="top">Meets the challenge but it doesn''t wow me. The composition looks top heavy and the light shining from beneath the pizza slice just confuses me.</td>', 'Meets the challenge but it doesn''t wow me. The composition looks top heavy and the light shining from beneath the pizza slice just confuses me.', '2004-04-28 20:54:08.000000', NULL, 1),
(689791, 72076, 7322, '<td valign="top">Decent framing of the subject matter but it lacks impact due to the washed out colors and lack of detail in the water. That thing coming up behind the ship and the structure at the right are visually distracting.</td>', 'Decent framing of the subject matter but it lacks impact due to the washed out colors and lack of detail in the water. That thing coming up behind the ship and the structure at the right are visually distracting.', '2004-04-28 20:56:07.000000', NULL, 1),
(689792, 72492, 2535, '<td valign="top">nice shot but i don''t get the proportions</td>', 'nice shot but i don''t get the proportions', '2004-04-28 20:56:09.000000', NULL, 1),
(689794, 71928, 2535, '<td valign="top">what''s the point?  i don''t SEE the proportion.  i know you are trying to suggest it through your title</td>', 'what''s the point?  i don''t SEE the proportion.  i know you are trying to suggest it through your title', '2004-04-28 20:57:46.000000', NULL, 1),
(689795, 71945, 2535, '<td valign="top">nice photo</td>', 'nice photo', '2004-04-28 20:58:44.000000', NULL, 1),
(689796, 72098, 7322, '<td valign="top">This looks a bit too much like a car ad. Lose the car and the tiny human and this would be improved greatly. The lone tree in the vast landscape makes the point without the jarring sight of an automobile. It needs more detail in the forergound with the tree perhaps in sillouhette since it is nearly there anyway.</td>', 'This looks a bit too much like a car ad. Lose the car and the tiny human and this would be improved greatly. The lone tree in the vast landscape makes the point without the jarring sight of an automobile. It needs more detail in the forergound with the tree perhaps in sillouhette since it is nearly there anyway.', '2004-04-28 20:58:45.000000', NULL, 1),
(689797, 72640, 2535, '<td valign="top">not worth it really</td>', 'not worth it really', '2004-04-28 20:59:40.000000', NULL, 1),
