(689815, 72499, 19256, '<td valign="top">You have nothing to show proportionality to the cat.</td>', 'You have nothing to show proportionality to the cat.', '2004-04-28 21:04:31.000000', NULL, 1),
(689818, 71980, 7322, '<td valign="top">This is a pretty, backlit shot of a dandelion. I''m not sure how it illustrates proportion. Cropping that strip of blurry sky at the top, and about 1/4 off the left edge would improve this imensely making it a nearly monocromatic image and letting the yellow really pop.  I would lose the green border.</td>', 'This is a pretty, backlit shot of a dandelion. I''m not sure how it illustrates proportion. Cropping that strip of blurry sky at the top, and about 1/4 off the left edge would improve this imensely making it a nearly monocromatic image and letting the yellow really pop.  I would lose the green border.', '2004-04-28 21:05:03.000000', NULL, 1),
(689819, 72727, 19256, '<td valign="top">There is nothing to show proportionality to the tree.</td>', 'There is nothing to show proportionality to the tree.', '2004-04-28 21:05:09.000000', NULL, 1),
