(689822, 71860, 7322, '<td valign="top">Beautiful, in-your-face animal portrait. My favorite kind of portrait. It doesn''t illustrate proportion so much as perspective so you lose points on not meeting the challenge. Outside the limitations of the challenge, it''s the best photograph I''ve seen today.</td>', 'Beautiful, in-your-face animal portrait. My favorite kind of portrait. It doesn''t illustrate proportion so much as perspective so you lose points on not meeting the challenge. Outside the limitations of the challenge, it''s the best photograph I''ve seen today.', '2004-04-28 21:07:18.000000', NULL, 1),
(689823, 72097, 19256, '<td valign="top">You have nothing to show proportionality. Awesome elephant, though.</td>', 'You have nothing to show proportionality. Awesome elephant, though.', '2004-04-28 21:07:38.000000', NULL, 1),
(689824, 72502, 19256, '<td valign="top">You have nothing to show proportionality.</td>', 'You have nothing to show proportionality.', '2004-04-28 21:08:07.000000', NULL, 1),
