(689919, 72190, 7322, '<td valign="top">This would have been more effective if you isolated a single bottle. And what the heck is that other thing off to the side? Without the title it doesn''t reveal much about proportion.</td>', 'This would have been more effective if you isolated a single bottle. And what the heck is that other thing off to the side? Without the title it doesn''t reveal much about proportion.', '2004-04-28 22:09:02.000000', NULL, 1),
(689940, 72578, 18838, '<td valign="top">redwoods are actually a good choice, but the pictures needs something in proportion to the tree ... e.g. somebody standing next to it?</td>', 'redwoods are actually a good choice, but the pictures needs something in proportion to the tree ... e.g. somebody standing next to it?', '2004-04-28 22:40:07.000000', NULL, 1),
