(695181, 71630, 19312, '<td valign="top">wow!!!!!</td>', 'wow!!!!!', '2004-05-03 12:39:45.000000', NULL, 1),
(695184, 72090, 19312, '<td valign="top">nice shot.....needs a better name...</td>', 'nice shot.....needs a better name...', '2004-05-03 12:41:06.000000', NULL, 1),
(695189, 72496, 12448, '<td valign="top">I bet it is.  Wow, um,  not really sure what to say here, LOL!  I see the lack of proportion so it fits the challenge but the picture does nothing for me except want to get you a pedicure! ;)  Slightly out of focus and just not very interesting overall.  A 3, sorry :(</td>', 'I bet it is.  Wow, um,  not really sure what to say here, LOL!  I see the lack of proportion so it fits the challenge but the picture does nothing for me except want to get you a pedicure! ;)  Slightly out of focus and just not very interesting overall.  A 3, sorry :(', '2004-05-03 12:42:55.000000', NULL, 1),
(695191, 71757, 19312, '<td valign="top">great shot...could use a simpler name</td>', 'great shot...could use a simpler name', '2004-05-03 12:43:14.000000', NULL, 1),
(695193, 71716, 12448, '<td valign="top">A good idea, bad execution :(  Too out of focus, no contrast and the size of the shot really leave me wanting something more.  A 3</td>', 'A good idea, bad execution :(  Too out of focus, no contrast and the size of the shot really leave me wanting something more.  A 3', '2004-05-03 12:43:56.000000', NULL, 1),
(695195, 71500, 12448, '<td valign="top">Okay!  Well, took me a moment to figure out where the title came from and then I saw it and got it.  Interesting idea but not very appealing overall and the post processing really hurt this shot to me.  I hope you didn''t draw that on the side just for this shot! ;)  A 3</td>', 'Okay!  Well, took me a moment to figure out where the title came from and then I saw it and got it.  Interesting idea but not very appealing overall and the post processing really hurt this shot to me.  I hope you didn''t draw that on the side just for this shot! ;)  A 3', '2004-05-03 12:45:22.000000', NULL, 1),
(695197, 71572, 12448, '<td valign="top">A good idea, wrong model for the car.  A die cast car, one more realistic might have really helped pull this shot off, especially if it was in a driveway and taken more from the ground angle, making the key look as big as the car either side by side or in front of the car.  a 4</td>', 'A good idea, wrong model for the car.  A die cast car, one more realistic might have really helped pull this shot off, especially if it was in a driveway and taken more from the ground angle, making the key look as big as the car either side by side or in front of the car.  a 4', '2004-05-03 12:46:46.000000', NULL, 1),
(695198, 71712, 12448, '<td valign="top">Yes, it might well be but it''s hard to tell from this picture.  I have nothing to compare it to and it''s out of focus and the reflection on the glass, especially towards the top is very distracting.  A 3</td>', 'Yes, it might well be but it''s hard to tell from this picture.  I have nothing to compare it to and it''s out of focus and the reflection on the glass, especially towards the top is very distracting.  A 3', '2004-05-03 12:48:04.000000', NULL, 1),
(695236, 71981, 20027, '<td valign="top">I like it but I have two suggestions: fix horizon so it is level and include the rest of the subject and position him at 1/3.</td>', 'I like it but I have two suggestions: fix horizon so it is level and include the rest of the subject and position him at 1/3.', '2004-05-03 13:16:59.000000', NULL, 1),
(695259, 72779, 15810, '<td valign="top">Brilliant....my winner by far....love it,  11 (if i could)</td>', 'Brilliant....my winner by far....love it,  11 (if i could)', '2004-05-03 13:41:30.000000', NULL, 1),
(695274, 72105, 11467, '<td valign="top">I love the simpleness of this image.</td>', 'I love the simpleness of this image.', '2004-05-03 13:58:43.000000', NULL, 1),
(695278, 71835, 11467, '<td valign="top">Excellent shot. Very well done. Even the frame which could have distracted seems to work ok on this image</td>', 'Excellent shot. Very well done. Even the frame which could have distracted seems to work ok on this image', '2004-05-03 14:00:09.000000', NULL, 1),
(695280, 72662, 17956, '<td valign="top">Great shot ! Congrats! Is that a wave in the background ?</td>', 'Great shot ! Congrats! Is that a wave in the background ?', '2004-05-03 14:00:53.000000', NULL, 1),
(695281, 71782, 11467, '<td valign="top">A slightly out of focus photo of ... er .. nothing!!</td>', 'A slightly out of focus photo of ... er .. nothing!!', '2004-05-03 14:01:18.000000', NULL, 1),
(695287, 71686, 11467, '<td valign="top">Focus is OK, but I don''t see the connection to Proportion, &amp; a snails bottom wouldn''t get a place on my living room wall!</td>', 'Focus is OK, but I don''t see the connection to Proportion, & a snails bottom wouldn''t get a place on my living room wall!', '2004-05-03 14:03:35.000000', NULL, 1),
(695292, 72530, 17956, '<td valign="top">Wha?! :))</td>', 'Wha?! :))', '2004-05-03 14:05:52.000000', NULL, 1),
(695342, 72753, 19670, '<td valign="top">Very nice colors, and good backround-to-foreground connection</td>', 'Very nice colors, and good backround-to-foreground connection', '2004-05-03 14:30:08.000000', NULL, 1),
(695347, 72673, 19670, '<td valign="top">Did you mean "bowling"? Bawling? Maybe bling-bling? :-)</td>', 'Did you mean "bowling"? Bawling? Maybe bling-bling? :-)', '2004-05-03 14:32:43.000000', NULL, 1),
