(695369, 71835, 19670, '<td valign="top">Very nicely set up!</td>', 'Very nicely set up!', '2004-05-03 14:40:32.000000', NULL, 1),
(695376, 72796, 19670, '<td valign="top">Might have tried cropping yourself out, or an angle that would have kept you out of the shot. A nice illusion.</td>', 'Might have tried cropping yourself out, or an angle that would have kept you out of the shot. A nice illusion.', '2004-05-03 14:42:39.000000', NULL, 1),
(695383, 72808, 19670, '<td valign="top">Suggest cropping the left side...</td>', 'Suggest cropping the left side...', '2004-05-03 14:45:20.000000', NULL, 1),
(695386, 72593, 19670, '<td valign="top">I''d prefer the baskets weren''t centered; top left area is distracting.</td>', 'I''d prefer the baskets weren''t centered; top left area is distracting.', '2004-05-03 14:47:56.000000', NULL, 1),
