INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(695474, 72672, 9780, '<td valign="top">nice choise of Sephia!<br/></td>', 'nice choise of Sephia!', '2004-05-03 15:34:43.000000', NULL, 1),
(695477, 72105, 19780, '<td valign="top">Wonderful sense of perspective. The texture of the sand is great. I''d love to see the end of the shadow and the grass fully in frame. The sky is great.<br/><br/><i>Message edited by author 2004-05-05 02:21:39.</i></td>', 'Wonderful sense of perspective. The texture of the sand is great. I''d love to see the end of the shadow and the grass fully in frame. The sky is great.', '2004-05-03 15:35:21.000000', '2004-05-05 03:21:39.000000', 1),
(695481, 72775, 19780, '<td valign="top">A wonderfully simple and understated choice. I like the black and white - it allows us to concentrate on the differences in size instead of flesh. I wish the left fellow was a little better lit across the lower back.</td>', 'A wonderfully simple and understated choice. I like the black and white - it allows us to concentrate on the differences in size instead of flesh. I wish the left fellow was a little better lit across the lower back.', '2004-05-03 15:36:49.000000', NULL, 1),
(695482, 72097, 9780, '<td valign="top">ahh nice shot... maybe to much crop?</td>', 'ahh nice shot... maybe to much crop?', '2004-05-03 15:36:58.000000', NULL, 1),
(695485, 72090, 9780, '<td valign="top">he he I would not meet this while I was burglering. :P</td>', 'he he I would not meet this while I was burglering. :P', '2004-05-03 15:38:34.000000', NULL, 1),
(695487, 72658, 9780, '<td valign="top">Ok this is funny pic.</td>', 'Ok this is funny pic.', '2004-05-03 15:39:10.000000', NULL, 1),
(695497, 72636, 9780, '<td valign="top">Like the framing. Nice DOF to</td>', 'Like the framing. Nice DOF to', '2004-05-03 15:43:28.000000', NULL, 1),
(695548, 71712, 21210, '<td valign="top">Why would you submit anything that isn''t in focus?</td>', 'Why would you submit anything that isn''t in focus?', '2004-05-03 16:09:33.000000', NULL, 1),
(695549, 72812, 21210, '<td valign="top">This isn''t in focus at all.</td>', 'This isn''t in focus at all.', '2004-05-03 16:10:24.000000', NULL, 1),
(695562, 72086, 21210, '<td valign="top">This doesn''t look like it is at all in focus. It is very pixelated. You may want to read a few books about composition - balance and harmony.</td>', 'This doesn''t look like it is at all in focus. It is very pixelated. You may want to read a few books about composition - balance and harmony.', '2004-05-03 16:14:16.000000', NULL, 1),
(695564, 71981, 21210, '<td valign="top">You can use the ruler tool in Photoshop to fix the horizon line from being on an angle.</td>', 'You can use the ruler tool in Photoshop to fix the horizon line from being on an angle.', '2004-05-03 16:14:54.000000', NULL, 1),
(695565, 71716, 21210, '<td valign="top">Why would you submit something that isn''t even in focus?</td>', 'Why would you submit something that isn''t even in focus?', '2004-05-03 16:15:12.000000', NULL, 1),
(695580, 72516, 19780, '<td valign="top">beautiful! would have qualified for serendipity too! I love the color difference between the two billboard designs and the darkness/definition on the arms of the man putting up the sign. The shadows really help to make it. I find the rooftop a little distracting, but a wonderful entry. good luck!</td>', 'beautiful! would have qualified for serendipity too! I love the color difference between the two billboard designs and the darkness/definition on the arms of the man putting up the sign. The shadows really help to make it. I find the rooftop a little distracting, but a wonderful entry. good luck!', '2004-05-03 16:21:18.000000', NULL, 1),
(695588, 72548, 21210, '<td valign="top">Looks a bit over-processed, but so far one of the nicest shots.</td>', 'Looks a bit over-processed, but so far one of the nicest shots.', '2004-05-03 16:26:18.000000', NULL, 1),
(695590, 72240, 21210, '<td valign="top">This looks really strange.</td>', 'This looks really strange.', '2004-05-03 16:27:43.000000', NULL, 1),
(695624, 72771, 7706, '<td valign="top">I am not quite sure how this photo relates to proportion, but I really like it. It looks really cool :)</td>', 'I am not quite sure how this photo relates to proportion, but I really like it. It looks really cool :)', '2004-05-03 16:58:09.000000', NULL, 1),
(695629, 72679, 7706, '<td valign="top">Great photo, but i think the border is a little bigger than needed and actually draws peoples attention away from image.</td>', 'Great photo, but i think the border is a little bigger than needed and actually draws peoples attention away from image.', '2004-05-03 17:06:13.000000', NULL, 1),
(695635, 72733, 7706, '<td valign="top">Would like to see teh image a little larger. Its hard to make details out when its so small.</td>', 'Would like to see teh image a little larger. Its hard to make details out when its so small.', '2004-05-03 17:14:54.000000', NULL, 1),
