(697429, 72807, 21202, '<td valign="top">I like that you really cleaned the piano keys and shined the door key.  Nice angles and lighting.  I also like that the door key is shown on edge and is not immediately recognizable.</td>', 'I like that you really cleaned the piano keys and shined the door key.  Nice angles and lighting.  I also like that the door key is shown on edge and is not immediately recognizable.', '2004-05-04 17:36:23.000000', NULL, 1),
(697430, 71829, 10918, '<td valign="top">The grass at the bottom is a touch visually distracting, and it would help if the colored wheel  was in focus, rather than the big one, however, I know that cameras with autofocus will make it near impossible to get what you want sometimes.  This is a great photo, great composition,  7.</td>', 'The grass at the bottom is a touch visually distracting, and it would help if the colored wheel  was in focus, rather than the big one, however, I know that cameras with autofocus will make it near impossible to get what you want sometimes.  This is a great photo, great composition,  7.', '2004-05-04 17:36:25.000000', NULL, 1),
(697432, 72123, 10918, '<td valign="top">Aaaahhh, there he is.</td>', 'Aaaahhh, there he is.', '2004-05-04 17:36:50.000000', NULL, 1),
(697433, 72226, 21202, '<td valign="top">NIce picture.</td>', 'NIce picture.', '2004-05-04 17:36:54.000000', NULL, 1),
(697440, 72448, 21202, '<td valign="top">Very nice.  Love the chairs, and the venetian blinds provide a perfect backdrop. Exactly the right amount of backlighting for silhouette.  I would like to see it cropped a little to the right.</td>', 'Very nice.  Love the chairs, and the venetian blinds provide a perfect backdrop. Exactly the right amount of backlighting for silhouette.  I would like to see it cropped a little to the right.', '2004-05-04 17:41:16.000000', NULL, 1),
(697447, 72717, 21202, '<td valign="top">Proportion well demonstrated.  Great depth of field for macro shot. I would like to see less of the top.  It draws my eye from bug.  Squashing potential of hand really evident.</td>', 'Proportion well demonstrated.  Great depth of field for macro shot. I would like to see less of the top.  It draws my eye from bug.  Squashing potential of hand really evident.', '2004-05-04 17:48:09.000000', NULL, 1),
(697449, 71669, 21202, '<td valign="top">Really nice perspective and mood. Lighting, clouds, snow, all fit. Nothing there that is not necessary, and nothing missing.  Great photo.  You get my first 10 for this challenge.</td>', 'Really nice perspective and mood. Lighting, clouds, snow, all fit. Nothing there that is not necessary, and nothing missing.  Great photo.  You get my first 10 for this challenge.', '2004-05-04 17:51:34.000000', NULL, 1),
(697451, 72672, 21202, '<td valign="top">Wonderful composition.</td>', 'Wonderful composition.', '2004-05-04 17:53:09.000000', NULL, 1),
(697454, 72447, 21202, '<td valign="top">I am a sucker for reflecting window.  I would like to see this with unbasic editing removing second building.</td>', 'I am a sucker for reflecting window.  I would like to see this with unbasic editing removing second building.', '2004-05-04 17:55:33.000000', NULL, 1),
