(697462, 72789, 21202, '<td valign="top">Great sense of humor and delightful model.  Nice choice of aperture.</td>', 'Great sense of humor and delightful model.  Nice choice of aperture.', '2004-05-04 18:04:13.000000', NULL, 1),
(697464, 72160, 21202, '<td valign="top">Was this bee so overpollunated it was unable to get away?  Good shot.</td>', 'Was this bee so overpollunated it was unable to get away?  Good shot.', '2004-05-04 18:05:38.000000', NULL, 1),
(697466, 72659, 21202, '<td valign="top">Love the reflections in the main drop.  Nice leaf forms.  You must be very pleased with the outcome.</td>', 'Love the reflections in the main drop.  Nice leaf forms.  You must be very pleased with the outcome.', '2004-05-04 18:07:36.000000', NULL, 1),
