(698860, 72571, 16862, '<td valign="top">Thanks for the comments, I didn´t expect so many to comment and I thougt I would finish at the bottom of this challenge.<br/>I´m really happy that I managed to make this picture say something and have a meaning, cause that´s the really hard and rewarding part of taking pictures.<br/> <br/>Thanks</td>', 'Thanks for the comments, I didn´t expect so many to comment and I thougt I would finish at the bottom of this challenge.I´m really happy that I managed to make this picture say something and have a meaning, cause that´s the really hard and rewarding part of taking pictures. Thanks', '2004-05-05 08:04:54.000000', NULL, 0),
(698871, 71835, 2158, '<td valign="top">Congratulations.  This was definitely my favourite.</td>', 'Congratulations.  This was definitely my favourite.', '2004-05-05 08:18:58.000000', NULL, 0),
(698880, 72597, 19196, '<td valign="top">Nice!<br/><br/><i>Message edited by author 2004-05-05 07:33:33.</i></td>', 'Nice!', '2004-05-05 08:30:26.000000', '2004-05-05 08:33:33.000000', 0),
(698894, 72508, 19196, '<td valign="top">Nice idea. Congratulations!</td>', 'Nice idea. Congratulations!', '2004-05-05 08:36:42.000000', NULL, 0),
(698904, 71835, 20577, '<td valign="top">Thank you all for the comments and votes! I was shocked that I finished so high. I put the border on to simulate a strike zone. I guess if you aren''t really into baseball then it didn''t make a whole lot of sense. I think it adds to the picture, but it will be the last border I ever use!<br/> <br/>Here is the original uncropped shot. The McFarlane figure is Kerry Wood. Other then cropping the image there were no adjustments. Hope you all aren''t disappointed!<br/> <br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=74591" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/20577/thumb/74591.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/20577/thumb/74591.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/20577/thumb/74591.jpg"/></a></td>', 'Thank you all for the comments and votes! I was shocked that I finished so high. I put the border on to simulate a strike zone. I guess if you aren''t really into baseball then it didn''t make a whole lot of sense. I think it adds to the picture, but it will be the last border I ever use! Here is the original uncropped shot. The McFarlane figure is Kerry Wood. Other then cropping the image there were no adjustments. Hope you all aren''t disappointed! ', '2004-05-05 08:41:50.000000', NULL, 0),
(698909, 72593, 19196, '<td valign="top">Somebody asked me about the title: Vegetal evolving may represent a proportional evolving of the chests and also a passage from the green leaf to the structured material used for the chests, all in the natural frame of the garden. <br/>The sun appeared and disappeared very quickly so there wasnt much time to arrange everything. Firstly I wanted to crop the black wood backyard but when trying to add a black border to the picture I observed how the backyard formed a natural odd border, with the plants going outside it. Therefore: only resize and sharpen, maybe was wrong, seeing the comments (for me it had a meaning, and I liked the contrast created). Anyhow I wish to thank to everybody who commented and voted!<br/></td>', 'Somebody asked me about the title: Vegetal evolving may represent a proportional evolving of the chests and also a passage from the green leaf to the structured material used for the chests, all in the natural frame of the garden. The sun appeared and disappeared very quickly so there wasnt much time to arrange everything. Firstly I wanted to crop the black wood backyard but when trying to add a black border to the picture I observed how the backyard formed a natural odd border, with the plants going outside it. Therefore: only resize and sharpen, maybe was wrong, seeing the comments (for me it had a meaning, and I liked the contrast created). Anyhow I wish to thank to everybody who commented and voted!', '2004-05-05 08:45:12.000000', NULL, 0),
(698912, 72084, 11960, '<td valign="top">The main goal, I guess, was to show the extremes people seemingly feel or <br/>display with out their coffee in the mornings... A parody of sorts on <br/>people that just can''t wake up and make it through the day without coffee... I <br/>wanted to show how out-of-proportion these people''s statements could be... <br/>Does that help?</td>', 'The main goal, I guess, was to show the extremes people seemingly feel or display with out their coffee in the mornings... A parody of sorts on people that just can''t wake up and make it through the day without coffee... I wanted to show how out-of-proportion these people''s statements could be... Does that help?', '2004-05-05 08:47:33.000000', NULL, 0),
(698920, 71835, 11793, '<td valign="top">what a sneaky shot - well done...</td>', 'what a sneaky shot - well done...', '2004-05-05 08:52:12.000000', NULL, 0),
(698933, 72771, 16430, '<td valign="top">The fact that the clips were all the same size and the colors were duplicated in the mirror, was my way of meeting the challenge. Thanks to everyone for your votes and comments.</td>', 'The fact that the clips were all the same size and the colors were duplicated in the mirror, was my way of meeting the challenge. Thanks to everyone for your votes and comments.', '2004-05-05 08:58:32.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(698935, 72508, 14603, '<td valign="top">Well thought out and worthy of the ribbon,<br/>Congratulations.<br/>Gordon</td>', 'Well thought out and worthy of the ribbon,Congratulations.Gordon', '2004-05-05 08:58:45.000000', NULL, 0),
(698941, 71835, 14603, '<td valign="top">Very creative,<br/>Well deserved ribbon...Congratulations,<br/>Gordon</td>', 'Very creative,Well deserved ribbon...Congratulations,Gordon', '2004-05-05 09:01:30.000000', NULL, 0),
(698953, 71809, 14603, '<td valign="top">I don`t understand why this got 74 - 5`s ??<br/>This was a top ten shot.<br/> <br/>Great work.<br/> <br/>Gordon</td>', 'I don`t understand why this got 74 - 5`s ??This was a top ten shot. Great work. Gordon', '2004-05-05 09:11:07.000000', NULL, 0),
(698954, 71835, 18374, '<td valign="top">Great shot!  I liked the strike zone / title combo.  It adds a story element to the picture and engages your mind as well as your eyes.</td>', 'Great shot!  I liked the strike zone / title combo.  It adds a story element to the picture and engages your mind as well as your eyes.', '2004-05-05 09:11:21.000000', NULL, 0),
(698963, 72515, 20204, '<td valign="top">After submitting this entry I had more time to study some post-processing techniques, and was able to create a much sharper (USM) and more saturated image.  I appreciate the comments - they definitely helped.<br/> <br/>I didn''t realize how critical the digital darkroom mastery was, or how crisp a picture my digicam was capable of until I got into this site.  That in itself was worth the yearly subscription!</td>', 'After submitting this entry I had more time to study some post-processing techniques, and was able to create a much sharper (USM) and more saturated image.  I appreciate the comments - they definitely helped. I didn''t realize how critical the digital darkroom mastery was, or how crisp a picture my digicam was capable of until I got into this site.  That in itself was worth the yearly subscription!', '2004-05-05 09:18:46.000000', NULL, 0),
(698966, 72793, 14603, '<td valign="top">This is the angle I wanted for my "Strength" submission..but the batteries ran out after one shot :(<br/> <br/>Always look forward to seeing your submissions Sher..as they are guaranteed to be good work...even if they are not always appreciated as much as they should be.<br/> <br/>Gordon</td>', 'This is the angle I wanted for my "Strength" submission..but the batteries ran out after one shot :( Always look forward to seeing your submissions Sher..as they are guaranteed to be good work...even if they are not always appreciated as much as they should be. Gordon', '2004-05-05 09:19:48.000000', NULL, 0),
(698978, 72508, 14836, '<td valign="top">Congratulation on your first ribbon ! Makes me almost jealous ! (LOL).</td>', 'Congratulation on your first ribbon ! Makes me almost jealous ! (LOL).', '2004-05-05 09:28:38.000000', NULL, 0),
(699011, 71809, 20247, '<td valign="top">I''m surprised that this didn''t receive more then it did.. I think it deserves a better score..</td>', 'I''m surprised that this didn''t receive more then it did.. I think it deserves a better score..', '2004-05-05 09:45:49.000000', NULL, 0),
(699036, 71812, 14255, '<td valign="top">Thanks to everyone who voted &amp; posted comments on my entry in the Proportions Challenge.</td>', 'Thanks to everyone who voted & posted comments on my entry in the Proportions Challenge.', '2004-05-05 10:00:16.000000', NULL, 0),
(699038, 71835, 2883, '<td valign="top">Ha! I guessed it! Even down to the pitchers name. hehe.... Congratulations</td>', 'Ha! I guessed it! Even down to the pitchers name. hehe.... Congratulations', '2004-05-05 10:03:33.000000', NULL, 0),
(699055, 71835, 16301, '<td valign="top">The best thing about McFarlane''s figures is that they look real, you used that to your advantage :) <br/> <br/>Congrats...</td>', 'The best thing about McFarlane''s figures is that they look real, you used that to your advantage :)  Congrats...', '2004-05-05 10:12:55.000000', NULL, 0),
(699057, 72795, 1368, '<td valign="top">Congratulations on a top ten! This is good stuff :)</td>', 'Congratulations on a top ten! This is good stuff :)', '2004-05-05 10:13:37.000000', NULL, 0),
(699060, 71835, 6870, '<td valign="top">Fun, dymanic shot!</td>', 'Fun, dymanic shot!', '2004-05-05 10:15:27.000000', NULL, 0),
(699064, 72508, 6870, '<td valign="top">What makes this photo really cool (one of the things, anyway), is the bored stare from the dog! Fun stuff!</td>', 'What makes this photo really cool (one of the things, anyway), is the bored stare from the dog! Fun stuff!', '2004-05-05 10:17:01.000000', NULL, 0),
(699074, 72735, 18216, '<td valign="top">Wow, I thought this would place higher. Great idea to fit the theme - I guess the background distracted too many people who perhaps felt this looked more like a snapshot.  I thought it was great and gave it a 9.<br/>:)</td>', 'Wow, I thought this would place higher. Great idea to fit the theme - I guess the background distracted too many people who perhaps felt this looked more like a snapshot.  I thought it was great and gave it a 9.:)', '2004-05-05 10:26:38.000000', NULL, 0),
(699077, 72774, 19670, '<td valign="top">I actually decided to use this one before realizing the swan boat was in the shot...serendipity! :-) I do wish it had more color.</td>', 'I actually decided to use this one before realizing the swan boat was in the shot...serendipity! :-) I do wish it had more color.', '2004-05-05 10:27:44.000000', NULL, 0),
(699084, 72748, 18216, '<td valign="top">Nice entry for this challenge!  I am very surprised that it did not rank higher. I am also surprised that there are so few comments. Overall, I really like the way that the picture is "framed" by the trees. The model is nicely posed, and I actually like the lens flare. The photo could perhaps be cleaned up a bit (Discoloration on the left, sky noise, flare "ring", etc.), but then it would not follow the rules. I gave it an 8.</td>', 'Nice entry for this challenge!  I am very surprised that it did not rank higher. I am also surprised that there are so few comments. Overall, I really like the way that the picture is "framed" by the trees. The model is nicely posed, and I actually like the lens flare. The photo could perhaps be cleaned up a bit (Discoloration on the left, sky noise, flare "ring", etc.), but then it would not follow the rules. I gave it an 8.', '2004-05-05 10:35:19.000000', NULL, 0),
(699131, 72518, 18216, '<td valign="top">I''m sure that you are disappointed with the placement in this challenge. It''s not often that I give a 10 for 148th place. lol.<br/>I''d like to see what this shot would look like redone, although I think it''s a great shot as is. The bottom is a bit distracting although I understand about wanting to get the base of the statue in the shot. I also like the shadows and light on the statue. The long flare does distract from the subject. Even though I''d already commented on this pic, I had to write again!  Keep up the good work.<br/><br/><i>Message edited by author 2004-05-05 10:08:48.</i></td>', 'I''m sure that you are disappointed with the placement in this challenge. It''s not often that I give a 10 for 148th place. lol.I''d like to see what this shot would look like redone, although I think it''s a great shot as is. The bottom is a bit distracting although I understand about wanting to get the base of the statue in the shot. I also like the shadows and light on the statue. The long flare does distract from the subject. Even though I''d already commented on this pic, I had to write again!  Keep up the good work.', '2004-05-05 11:08:19.000000', '2004-05-05 11:08:48.000000', 0),
(699151, 71973, 11467, '<td valign="top">Ha, You like this shot, coz it makes you look thin!!!<br/>Actually it is pretty cook. A shame that the movement in the background looks like out of focus. Probably using a faster shutter would help, but as the aperature was already at 2.8, you obviously were lacking light somewhat.</td>', 'Ha, You like this shot, coz it makes you look thin!!!Actually it is pretty cook. A shame that the movement in the background looks like out of focus. Probably using a faster shutter would help, but as the aperature was already at 2.8, you obviously were lacking light somewhat.', '2004-05-05 11:21:21.000000', NULL, 0),
(699154, 71835, 16862, '<td valign="top">brilliant</td>', 'brilliant', '2004-05-05 11:22:15.000000', NULL, 0),
(699229, 72773, 16862, '<td valign="top">Proportion</td>', 'Proportion', '2004-05-05 11:57:25.000000', NULL, 0),
(699231, 72548, 16862, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by budokan:</b></div><hr/><i> This should be good but for some reason it fails to inspire - possibly the image quality is too low and there''s nothing really gripping about the picture, like a shade of red or light green to brighten it up </i></td></tr></table> <br/> <br/>I agree</td>', 'Originally posted by budokan: This should be good but for some reason it fails to inspire - possibly the image quality is too low and there''s nothing really gripping about the picture, like a shade of red or light green to brighten it up   I agree', '2004-05-05 11:58:28.000000', NULL, 0),
(699238, 72098, 16862, '<td valign="top">Very good - needs some more cropping</td>', 'Very good - needs some more cropping', '2004-05-05 12:01:39.000000', NULL, 0),
(699240, 72770, 14386, '<td valign="top">Congratulations Lauriel! Well-deserved placing.<br/> <br/>I will send the postcard late this week. I had it printed today and pick it up on Friday.<br/> <br/>Manny (librodo)<br/> <br/>PS. I think you''ll make it to top 10. The blue ribbon winner admitted he broke the rules in PP. What a pity...it is such a nice shot. <br/><br/><i>Message edited by author 2004-05-05 11:08:04.</i></td>', 'Congratulations Lauriel! Well-deserved placing. I will send the postcard late this week. I had it printed today and pick it up on Friday. Manny (librodo) PS. I think you''ll make it to top 10. The blue ribbon winner admitted he broke the rules in PP. What a pity...it is such a nice shot. ', '2004-05-05 12:02:23.000000', '2004-05-05 12:08:04.000000', 0),
(699261, 71835, 14386, '<td valign="top">Congratulations to the BLUE ribbon. Well-deserved. Your idea is great. an dthe picture is well balanced. <br/> <br/>librodo (Manny)</td>', 'Congratulations to the BLUE ribbon. Well-deserved. Your idea is great. an dthe picture is well balanced.  librodo (Manny)', '2004-05-05 12:11:57.000000', NULL, 0),
(699339, 71809, 16095, '<td valign="top">Thanks to all the great comments -on how I got the scissors to stand on their own-I placed a sheet of butcher paper on an old wood floor and placed the scissors in the ruts-thru the paper.</td>', 'Thanks to all the great comments -on how I got the scissors to stand on their own-I placed a sheet of butcher paper on an old wood floor and placed the scissors in the ruts-thru the paper.', '2004-05-05 12:43:51.000000', NULL, 0),
(699383, 72625, 12151, '<td valign="top">As expected this great photo didn''t place at the top.  Don''t be discouraged by majority vote.  This is an excellent image.<br/><br/><i>Message edited by author 2004-05-05 12:20:24.</i></td>', 'As expected this great photo didn''t place at the top.  Don''t be discouraged by majority vote.  This is an excellent image.', '2004-05-05 13:20:07.000000', '2004-05-05 13:20:24.000000', 0),
(699388, 71835, 18349, '<td valign="top">This is a WOO-HOO moment!!! Congrats!  And I owe my ten-year old $5.00 since he bet me it was Kerry Wood!!!</td>', 'This is a WOO-HOO moment!!! Congrats!  And I owe my ten-year old $5.00 since he bet me it was Kerry Wood!!!', '2004-05-05 13:24:49.000000', NULL, 0),
(699547, 72779, 20613, '<td valign="top">That''s hilarious.  I love this shot.</td>', 'That''s hilarious.  I love this shot.', '2004-05-05 14:23:00.000000', NULL, 0),
(699663, 72793, 3032, '<td valign="top">Hi Sher,<br/> <br/>I thought it was your pic (Natchez, no doubt) but had not given much thought to the title. Aren''t most of your photos that feature this bridge taken from the other side? That''s another "over the bridge". :)<br/> <br/>Isn''t there a hotel on a hill to the right? Stayed there for a night a couple of years ago.<br/> <br/>I like this composition, but the toning/light is a bit dull.<br/>"Storms over the Mississippi" was great btw.<br/> <br/>Sorry for not showing up at fanatics lately. ;) <img alt="'' . substr(''//www.pbase.com/image/28658741.jpg'', strrpos(''//www.pbase.com/image/28658741.jpg'', ''/'') + 1) . ''" border="0" src="//www.pbase.com/image/28658741.jpg"/></td>', 'Hi Sher, I thought it was your pic (Natchez, no doubt) but had not given much thought to the title. Aren''t most of your photos that feature this bridge taken from the other side? That''s another "over the bridge". :) Isn''t there a hotel on a hill to the right? Stayed there for a night a couple of years ago. I like this composition, but the toning/light is a bit dull."Storms over the Mississippi" was great btw. Sorry for not showing up at fanatics lately. ;) ', '2004-05-05 15:04:06.000000', NULL, 0),
(699676, 72625, 3032, '<td valign="top">I loved this idea and how it turned out. Disappointing to see it score so low.</td>', 'I loved this idea and how it turned out. Disappointing to see it score so low.', '2004-05-05 15:09:05.000000', NULL, 0),
(699790, 72448, 14614, '<td valign="top">Thanks to all who voted and comments.  I found all your comments helpful.  On this challenge I also learned all about the dq process although I''m not sure why as it was a very minimally edited shot. :)<br/> <br/></td>', 'Thanks to all who voted and comments.  I found all your comments helpful.  On this challenge I also learned all about the dq process although I''m not sure why as it was a very minimally edited shot. :) ', '2004-05-05 16:10:29.000000', NULL, 0),
