(700273, 72649, 12362, '<td valign="top">You deserved to win this challenge, but congrats on the (late) ribbon : )</td>', 'You deserved to win this challenge, but congrats on the (late) ribbon : )', '2004-05-05 19:45:41.000000', NULL, 0),
